#!/usr/bin/env python3
"""Synchronize generated release metadata from VERSION; --check never writes."""
import argparse
import json
import pathlib
import re

root = pathlib.Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser()
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
version = (root / "VERSION").read_text().strip()
if not re.fullmatch(r"\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.-]+)?", version):
    raise SystemExit("invalid VERSION")
updates = {}
updates["internal/metadata/version_generated.go"] = (
    "// Code generated by scripts/sync-metadata.py from VERSION; DO NOT EDIT.\n"
    f'package metadata\n\nconst Version = "{version}"\n'
)
for name in ("package.json", "package-lock.json"):
    data = json.loads((root / name).read_text())
    data["version"] = version
    if name == "package-lock.json":
        data.get("packages", {}).get("", {})["version"] = version
    updates[name] = json.dumps(data, indent=2, ensure_ascii=False) + "\n"
readme = (root / "README.md").read_text()
readme, count = re.subn(
    r"当前工作版本：\*\*[^*]+\*\*", f"当前工作版本：**{version}**", readme, count=1
)
if count != 1:
    raise SystemExit("README version marker missing")
updates["README.md"] = readme
stale = [name for name, value in updates.items() if not (root / name).exists() or (root / name).read_text() != value]
if args.check and stale:
    raise SystemExit("metadata is stale: " + ", ".join(stale))
if not args.check:
    for name, value in updates.items():
        (root / name).parent.mkdir(parents=True, exist_ok=True)
        (root / name).write_text(value)
print("Release metadata verified: " + version)
